import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))+"/out")
from h18 import *
"""Linked features: a card added to the roadmap keeps its title and progress linked with the roadmap bar and the weekly-report items (by feature id).
Changes from Monthly / the report wait for an admin; roadmap changes are checked one by one. Fake test database only."""
R=[]
def ok(n,c): R.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as pw:
    b=pw.chromium.launch(); ctx=mkctx(b); ctx.clock.set_fixed_time("2026-10-20T10:00:00"); errs=[]
    A=newpage(ctx,errs); signup(A,'Admin','adm@x.com')
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(800)
    oc=A.locator('.mdcol[data-mo="2026-10"]'); oc.locator('.mdopen').click(); ta=oc.locator('.mdadd textarea'); ta.fill('Link me'); ta.press('Enter'); A.wait_for_timeout(500); A.keyboard.press('Escape'); A.wait_for_timeout(300)
    card=lambda t: oc.locator('.mdcard:has-text("%s")'%t)
    card('Link me').locator('select[aria-label="Percent complete"]').select_option('20'); A.wait_for_timeout(400)
    fid=card('Link me').locator('.mdid').inner_text()
    card('Link me').locator('.kebab').click(); A.wait_for_timeout(200); A.locator('#ctx .mi:has-text("Add to roadmap")').click(); A.wait_for_timeout(300)
    A.fill('#xdlg [aria-label="Start date"]','2026-10-20'); A.fill('#xdlg [aria-label="End date"]','2026-10-30'); A.click('#xdlg button:text-is("Add to roadmap")'); A.wait_for_timeout(900)
    ok('L1 the card is on the roadmap and starts in step (no chips)', card('Link me').locator('.mdroad').count()==1 and card('Link me').locator('.fschip').count()==0)
    ok('L2 the roadmap bar starts with the card progress', A.evaluate("()=>Object.values(JSON.parse(localStorage.getItem('fk3')).items).some(x=>x&&x.t==='Link me'&&x.pc===20)"))
    # card edits wait for the admin
    t=card('Link me').locator('.mdtext'); t.fill('Link me v2'); t.press('Tab'); A.wait_for_timeout(500)
    card('Link me v2').locator('select[aria-label="Percent complete"]').select_option('50'); A.wait_for_timeout(500)
    ok('L3 after editing, the card says it waits for an admin', card('Link me v2').locator('.fschip.out').count()==1)
    bar=lambda: A.evaluate("()=>{const o=JSON.parse(localStorage.getItem('fk3')).items;const k=Object.keys(o).find(i=>o[i]&&o[i].card);return k?o[k]:null}")
    d=bar(); ok('L4 the roadmap bar is unchanged until approved (title and 20%)', d and d['t']=='Link me' and d.get('pc')==20)
    A.click('#nav button[data-p="admin"]'); A.wait_for_timeout(900)
    ok('L5 the admin sees two requests (title and progress)', A.locator('#roadreq .fsrow').count()==2 and 'Roadmap update requests (2)' in A.locator('#roadreq h2').inner_text())
    ok('L6 the nav dot counts the requests', A.locator('#nav [data-p="admin"] .dot').inner_text().strip()=='2')
    A.locator('#roadreq button[aria-label="Approve Title of %s"]'%fid).click(); A.wait_for_timeout(600)
    A.locator('#roadreq button[aria-label="Approve Progress of %s"]'%fid).click(); A.wait_for_timeout(600)
    d=bar(); ok('L7 approving updates the roadmap bar', d and d['t']=='Link me v2' and d.get('pc')==50)
    ok('L8 no request is left', A.locator('#roadreq .fsrow').count()==0)
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(700)
    ok('L9 the card is in step again', card('Link me v2').locator('.fschip').count()==0 and A.locator('#mdcheck').count()==0)
    # weekly report item by id
    A.evaluate("""()=>{const d=JSON.parse(localStorage.getItem('fk3'));d.sprints.sp1={n:1,a:'2026-10-12',b:'2026-10-25',note:'',secs:{tifli:{people:['Lea']}}};localStorage.setItem('fk3',JSON.stringify(d));}"""); A.reload(); A.wait_for_timeout(1500)
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(400); A.click('button:has-text("New report for week of")'); A.wait_for_timeout(700)
    tf=A.locator('#pg-reports .rprod[data-k="tifli"]'); tf.locator('.spadd textarea').fill('Report copy'); tf.locator('button:text-is("Add items")').click(); A.wait_for_timeout(500)
    fi=A.locator('#pg-reports .rline input[aria-label^="Feature id"]').first
    fi.fill('XX#999'); fi.press('Tab'); A.wait_for_timeout(400)
    ok('L10 an unknown id is refused', A.locator('#pg-reports .rline .fschip').count()==0 and fi.input_value()=='')
    fi.fill(fid.lower()); fi.press('Tab'); A.wait_for_timeout(600)
    ok('L11 the item links by id (any letter case)', A.locator('#pg-reports .rline input[aria-label^="Feature id"]').first.input_value()==fid)
    ok('L12 the roadmap title/progress differ, so the report offers Check updates', A.locator('#rpcheck').count()==1 and A.locator('#pg-reports .rline .fschip.in').count()==1)
    A.click('#rpcheck'); A.wait_for_timeout(300)
    ok('L13 the dialog lists title and progress separately', A.locator('#xdlg .fsrow').count()==2)
    A.locator('#xdlg button[aria-label="Apply Title of %s"]'%fid).click(); A.wait_for_timeout(500)
    ok('L14 applying one change leaves the other for you to decide', A.locator('#xdlg .fsrow').count()==1)
    A.locator('#xdlg button[aria-label="Apply Progress of %s"]'%fid).click(); A.wait_for_timeout(500); A.click('#xdlg button:text-is("Close")'); A.wait_for_timeout(500)
    ok('L15 the report item took the roadmap title and 50%', 'Link me v2' in A.locator('#pg-reports .rline .sptext').first.inner_text() and A.locator('#pg-reports .rline select[aria-label="Percent complete"]').first.input_value()=='50' and A.locator('#rpcheck').count()==0)
    # progress changed on the roadmap
    A.click('#nav button[data-p="roadmap"]'); A.wait_for_timeout(700)
    bid=A.evaluate("()=>{const o=JSON.parse(localStorage.getItem('fk3')).items;return Object.keys(o).find(i=>o[i]&&o[i].card)}")
    bl=A.locator('.bar[data-id="%s"]'%bid).first; bl.scroll_into_view_if_needed(); bl.click(button='right'); A.wait_for_timeout(300)
    ok('L16 the bar menu shows the progress and the linked id', A.locator('#ctx select[aria-label="Progress"]').count()==1 and fid in A.locator('#ctx').inner_text())
    A.locator('#ctx select[aria-label="Progress"]').select_option('80'); A.wait_for_timeout(600)
    ok('L17 the bar shows its progress', A.locator('.bar[data-id="%s"] .pgf'%bid).first.evaluate("e=>e.style.width")=='80%')
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(800)
    ok('L18 Monthly offers Check updates (1) and marks the card', A.locator('#mdcheck').inner_text()=='Check updates (1)' and card('Link me v2').locator('.fschip.in').count()==1)
    A.click('#mdcheck'); A.wait_for_timeout(300); A.locator('#xdlg button[aria-label="Apply Progress of %s"]'%fid).click(); A.wait_for_timeout(500); A.click('#xdlg button:text-is("Close")'); A.wait_for_timeout(500)
    ok('L19 the card now shows 80%', card('Link me v2').locator('select[aria-label="Percent complete"]').input_value()=='80' and A.locator('#mdcheck').count()==0)
    # the report item: keep mine -> request -> reject
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(500); A.locator('#pg-reports .rlist, #pg-reports').first
    A.locator('#pg-reports .rpcard a.splink').first.click(); A.wait_for_timeout(600)
    A.click('#rpcheck'); A.wait_for_timeout(300); A.locator('#xdlg button[aria-label="Keep mine for Progress of %s"]'%fid).click(); A.wait_for_timeout(500); A.click('#xdlg button:text-is("Close")'); A.wait_for_timeout(400)
    ok('L20 "Keep mine" turns the item into a request', A.locator('#pg-reports .rline .fschip.out').count()==1)
    A.click('#nav button[data-p="admin"]'); A.wait_for_timeout(900)
    ok('L21 the admin sees the request from the weekly report', A.locator('#roadreq .fsrow').count()==1 and 'weekly report' in A.locator('#roadreq').inner_text() and '80%' in A.locator('#roadreq .fsdiff').inner_text())
    A.locator('#roadreq button[aria-label="Reject Progress of %s"]'%fid).click(); A.wait_for_timeout(600)
    ok('L22 rejecting sends the item back to the roadmap value', A.locator('#roadreq .fsrow').count()==0)
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(500); A.locator('#pg-reports .rpcard a.splink').first.click(); A.wait_for_timeout(600)
    ok('L23 the report item is 80% again', A.locator('#pg-reports .rline select[aria-label="Percent complete"]').first.input_value()=='80' and A.locator('#pg-reports .rline .fschip').count()==0)
    ok('no page errors', errs==[]); print('errors:',errs[:3])
    print(sum(1 for _,c in R if c),'/',len(R))
